    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    // 20% of 1000 = 200
    expect(result.totals.taxCents).toBe(200);
  });

  it("combines discount + async tax + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US" });
    cart.add(productA, 2); // subtotal 2000, discount 200, discounted 1800
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // tax: 10% of 1800 = 180
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.shippingCents).toBe(500);
    // total: 1800 + 180 + 500 = 2480
    expect(result.totals.totalCents).toBe(2480);
  });

  it("propagates priceFetcher error", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("service down");
