toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts 0 for flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 for freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for normal cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2000)).toBe(599);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOverCents threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal below freeOverCents", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4999)).toBe(599);
    });

    it("returns flat fee when no freeOverCents configured", () => {
      const calc = new FlatShippingCalculator(799);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 100_000)).toBe(799);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 5.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, -1),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () => new WeightBasedShippingCalculator(brackets, 5.5),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects first bracket matching weight", () => {
      // 400g → first bracket (up to 500g, 300 cents)
      expect(calc.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    });

    it("selects bracket at exact boundary", () => {
      // 500g → first bracket (up to 500g, 300 cents)
      expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds boundary", () => {
      // 501g → second bracket (up to 1000g, 600 cents)
      expect(calc.computeShippingCents([makeLine("a", 501, 1)], 5000)).toBe(600);
    });

    it("selects highest bracket for weight at its boundary", () => {
      // 5000g → third bracket (up to 5000g, 1200 cents)
      expect(calc.computeShippingCents([makeLine("a", 5000, 1)], 5000)).toBe(1200);
    });

    it("uses last bracket cost as overflow when no overflowCostCents", () => {
      // 6000g exceeds all brackets
      expect(calc.computeShippingCents([makeLine("a", 6000, 1)], 5000)).toBe(1200);
    });

    it("uses overflowCostCents when configured and weight exceeds all brackets", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(brackets, 2000);
      expect(calcWithOverflow.computeShippingCents([makeLine("a", 6000, 1)], 5000)).toBe(2000);
    });

    it("sums weight across multiple lines", () => {
      // 300g * 2 + 500g * 1 = 1100g → third bracket (up to 5000g, 1200 cents)
      const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("sorts brackets regardless of input order", () => {
      const unsorted: WeightBracket[] = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const c = new WeightBasedShippingCalculator(unsorted);
      expect(c.computeShippingCents([makeLine("a", 400, 1)], 5000)).toBe(300);
    });
  });
});

